![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

The current implementation of `bboxFromObject` and `bboxFromArray` returns incomplete bounding box objects (with `null` values for width/height or coordinates) when some properties are missing or invalid. According to the general rules, the extraction process must skip spans that do not have a valid, complete, and finite bounding box, returning `null` if no valid bounding box can be constructed.

```javascript
function bboxFromObject(bbox) {
  if (!bbox || typeof bbox !== 'object' || Array.isArray(bbox)) return null;
  if ('x' in bbox || 'y' in bbox || 'width' in bbox || 'height' in bbox) {
    const x = numeric(bbox.x);
    const y = numeric(bbox.y);
    const width = numeric(bbox.width);
    const height = numeric(bbox.height);
    if (x === null || y === null || width === null || height === null || !Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(width) || !Number.isFinite(height)) {
      return null;
    }
    return {
      x,
      y,
      width,
      height,
      unit: bbox.unit ?? bbox.units ?? null,
    };
  }
  if ('x1' in bbox || 'y1' in bbox || 'x2' in bbox || 'y2' in bbox) {
    const x1 = numeric(bbox.x1);
    const y1 = numeric(bbox.y1);
    const x2 = numeric(bbox.x2);
    const y2 = numeric(bbox.y2);
    if (x1 === null || y1 === null || x2 === null || y2 === null || !Number.isFinite(x1) || !Number.isFinite(y1) || !Number.isFinite(x2) || !Number.isFinite(y2)) {
      return null;
    }
    return {
      x: x1,
      y: y1,
      width: x2 - x1,
      height: y2 - y1,
      unit: bbox.unit ?? bbox.units ?? null,
    };
  }
  return null;
}

function bboxFromArray(bbox) {
  if (!Array.isArray(bbox) || bbox.length !== 4) return null;
  const [x1, y1, x2, y2] = bbox.map(numeric);
  if (x1 === null || y1 === null || x2 === null || y2 === null || !Number.isFinite(x1) || !Number.isFinite(y1) || !Number.isFinite(x2) || !Number.isFinite(y2)) {
    return null;
  }
  return {
    x: x1,
    y: y1,
    width: x2 - x1,
    height: y2 - y1,
    unit: 'normalized',
  };
}
```

